using System;using System.Collections.Generic;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using TMPro;using LWS.TruckBowling;using LWS.TruckHockey;
namespace LWS.TruckSports {
// Per-source input/audio coordination only. Installed NWH recordings remain the
// horn foundation; an owned looping voice also works while a launch disables
// the NWH powertrain. This adapter never writes vehicle inputs or physics.
[DefaultExecutionOrder(650)]
public sealed class SportsUniversalHorn:MonoBehaviour {
 public struct Driver { public BowlingSource source;public Gamepad pad;public Key forward,left,back,right,action;public bool released,allowed; }
 Func<int,Driver> driver;Func<int> count;Func<bool> live;Func<float> gain;Func<int,Transform> position;Func<Key,bool> extraReserved;MonoBehaviour owner;
 readonly AudioSource[] voices=new AudioSource[16];readonly bool[] armed=new bool[16];readonly Key[] keys=new Key[16];readonly HashSet<Key> used=new HashSet<Key>();readonly StringBuilder text=new StringBuilder(256);SportsHornAssets assets;TMP_Text help;int signature=int.MinValue;bool focused=true;
 public int Starts{get;private set;}public int ActiveVoices{get{int n=0;foreach(var voice in voices)if(voice!=null&&voice.isPlaying)n++;return n;}}
 public int ConfiguredCount=>count!=null?count():0;public bool InputReady(int slot)=>driver!=null&&live()&&driver(slot).released&&driver(slot).allowed;public string Caption{get;private set;}="HORN";public Key HornKey(int slot)=>keys[slot];public AudioSource Voice(int slot)=>voices[slot];public Transform EmitterAnchor(int slot)=>position(slot);
 static readonly Key[] preferred={Key.V,Key.Home,Key.Comma,Key.Slash,Key.F9,Key.F10,Key.F11,Key.F12,Key.F1,Key.F2,Key.F3,Key.F4,Key.F5,Key.F6,Key.F7,Key.F8};
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){SceneManager.sceneLoaded-=Loaded;SceneManager.sceneLoaded+=Loaded;Loaded(SceneManager.GetActiveScene(),LoadSceneMode.Single);}
 static void Loaded(Scene scene,LoadSceneMode mode){
  foreach(var m in UnityEngine.Object.FindObjectsByType<SportsEventSession>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null&&!(m is LWS.TruckSnake.SnakeMatch)&&!(m is LWS.TruckFareFight.FareFightMatch))Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<BowlingMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<LWS.TruckCornhole.CornholeMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<LWS.TruckCheeseRolling.CheeseMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<HockeyMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<LWS.TruckAirHockey.AirHockeyMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<LWS.TruckWallball.WallballMatch>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
  foreach(var m in UnityEngine.Object.FindObjectsByType<LWS.TruckBilliards.BilliardsSession>(FindObjectsInactive.Include))if(m.gameObject.scene==scene&&m.GetComponent<SportsUniversalHorn>()==null)Attach(m);
 }
 static Driver From(BowlingPlayer p,Key action=Key.None,bool allowed=true)=>new Driver{source=p.source,pad=p.pad,forward=p.forward,left=p.left,back=p.back,right=p.right,action=action,released=p.released,allowed=allowed};
 static Driver From(HockeyPlayer p,Key action=Key.None)=>new Driver{source=(BowlingSource)p.source,pad=p.pad,forward=p.forward,left=p.left,back=p.back,right=p.right,action=action,released=p.released,allowed=true};
 static SportsUniversalHorn Add(MonoBehaviour owner,Transform page){var h=owner.gameObject.AddComponent<SportsUniversalHorn>();h.owner=owner;h.assets=Resources.Load<SportsHornAssets>("SportsHornAssets");if(h.assets==null||h.assets.defaultHorn==null)throw new InvalidOperationException("Truck Sports shared installed horn asset is missing.");for(int i=0;i<h.voices.Length;i++){var go=new GameObject("Owned spatial horn voice "+(i+1));go.transform.SetParent(owner.transform,false);var voice=go.AddComponent<AudioSource>();voice.playOnAwake=false;voice.loop=true;voice.clip=h.assets.defaultHorn;voice.spatialBlend=.7f;voice.minDistance=5;voice.maxDistance=180;voice.rolloffMode=AudioRolloffMode.Logarithmic;voice.dopplerLevel=0;h.voices[i]=voice;}if(page!=null){var go=new GameObject("Actual dedicated horn bindings",typeof(RectTransform));go.transform.SetParent(page,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(1280,42);r.anchoredPosition=new Vector2(0,-345);h.help=go.AddComponent<TextMeshProUGUI>();h.help.font=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;h.help.fontSize=20;h.help.alignment=TextAlignmentOptions.Center;h.help.color=new Color(1,.9f,.62f);h.help.raycastTarget=false;}return h;}
 public static SportsUniversalHorn Attach(SportsEventSession m){var h=Add(m,m.menus.pages[(int)SportsEventScreen.Help].transform);var trucks=UnityEngine.Object.FindObjectsByType<SportsEventTruck>(FindObjectsInactive.Include);h.driver=i=>From(m.setup.players[i],m.actionKeys[i],!(m is LWS.TruckPoker.PokerMatch poker)||!poker.HotSeat||poker.Table!=null&&poker.Table.Actor==i&&!poker.Handoff&&!poker.Dealing);h.count=()=>m.setup.count;h.live=()=>m.Live&&!m.ReplayControls;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>{if(m is LWS.TruckCurling.CurlingMatch curling)return i==curling.ActiveSlot&&curling.Current!=null?curling.Current.truck.transform:null;if(m is LWS.TruckDockDiving.DockMatch dock&&i==dock.Active)return dock.truck.transform;if(m is LWS.TruckDerby.DerbyMatch derby)return derby.fighters[i].transform;if(m is LWS.TruckPoker.PokerMatch poker)return poker.avatars[i];Transform result=null;foreach(var t in trucks)if(t!=null&&t.session==m&&t.slot==i&&t.gameObject.activeInHierarchy)result=t.transform;return result;};h.extraReserved=k=>{if(m is LWS.TruckPoker.PokerMatch poker)for(int i=0;i<m.setup.count;i++)if(poker.PeekKey(i)==k)return true;if(m is LWS.TruckPedestrianPlowing.PlowMatch plow&&plow.cabExperience){var extras=plow.GetComponent<LWS.TruckPedestrianPlowing.PlowCabExtras>();if(extras!=null)foreach(var key in extras.holdKeys)if(key==k)return true;if(extras!=null)foreach(var key in extras.cueKeys)if(key==k)return true;}return k==Key.Tab||k==Key.C||k==Key.E||k==Key.Q;};return h;}
 public static SportsUniversalHorn Attach(BowlingMatch m){var h=Add(m,m.menus.pages[(int)BowlingScreen.Help].transform);h.count=()=>m.setup.count;h.driver=i=>From(m.setup.players[i],Key.Tab,m.setup.mode!=BowlingMode.HotSeat||m.ActiveSlot==i);h.live=()=>m.InMatch&&!m.Paused&&!m.Finished&&m.menus.Screen==BowlingScreen.Play;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.lanes[m.setup.mode==BowlingMode.HotSeat?0:i].truck.transform;return h;}
 public static SportsUniversalHorn Attach(LWS.TruckCornhole.CornholeMatch m){var h=Add(m,m.menus.pages[(int)LWS.TruckCornhole.CornholeScreen.Help].transform);h.count=()=>m.setup.count;h.driver=i=>From(m.setup.players[i]);h.live=()=>m.InMatch&&!m.Paused&&!m.Finished;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.courses[i].Current!=null?m.courses[i].Current.transform:null;return h;}
 public static SportsUniversalHorn Attach(LWS.TruckCheeseRolling.CheeseMatch m){var h=Add(m,m.menus.pages[(int)LWS.TruckCheeseRolling.CheeseScreen.Help].transform);h.count=()=>m.setup.count;h.driver=i=>From(m.setup.players[i]);h.live=()=>m.InMatch&&!m.Paused&&!m.Finished;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.trucks[i].transform;return h;}
 public static SportsUniversalHorn Attach(HockeyMatch m){var h=Add(m,m.menus.pages[(int)HockeyScreen.Help].transform);h.count=()=>m.players.Length;h.driver=i=>From(m.players[i]);h.live=()=>m.InMatch&&!m.MenuOpen;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.trucks[i].transform;return h;}
 public static SportsUniversalHorn Attach(LWS.TruckAirHockey.AirHockeyMatch m){var h=Add(m,m.menus.pages[(int)LWS.TruckAirHockey.AirHockeyScreen.Help].transform);h.count=()=>m.players.Length;h.driver=i=>From(m.players[i]);h.live=()=>m.InMatch&&!m.MenuOpen;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.trucks[i].transform;return h;}
 public static SportsUniversalHorn Attach(LWS.TruckWallball.WallballMatch m){var h=Add(m,m.menus.pages[(int)LWS.TruckWallball.WallballScreen.Help].transform);h.count=()=>m.Count;h.driver=i=>From(m.players[i],m.jumpKeys[i]);h.live=()=>m.InMatch&&!m.MenuOpen;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.trucks[i].transform;return h;}
 public static SportsUniversalHorn Attach(LWS.TruckBilliards.BilliardsSession m){var h=Add(m,m.menus.pages[(int)LWS.TruckBilliards.BilliardsScreen.Help].transform);h.count=()=>m.IsPractice?1:2;h.driver=i=>{var p=m.players[i];bool shared=m.mode==LWS.TruckBilliards.BilliardsMode.HotSeat||m.IsPractice;return new Driver{source=p.control==LWS.TruckBilliards.BilliardsControl.AI?BowlingSource.AI:p.control==LWS.TruckBilliards.BilliardsControl.Gamepad?BowlingSource.WholeController:BowlingSource.Keyboard,pad=m.mode==LWS.TruckBilliards.BilliardsMode.HotSeat?m.SharedPad:p.pad,forward=p.control==LWS.TruckBilliards.BilliardsControl.KeyboardArrows?Key.UpArrow:Key.W,left=p.control==LWS.TruckBilliards.BilliardsControl.KeyboardArrows?Key.LeftArrow:Key.A,back=p.control==LWS.TruckBilliards.BilliardsControl.KeyboardArrows?Key.DownArrow:Key.S,right=p.control==LWS.TruckBilliards.BilliardsControl.KeyboardArrows?Key.RightArrow:Key.D,released=p.released,allowed=!shared||m.match.rules.Turn==i};};h.live=()=>m.GameplayEnabled;h.gain=()=>m.settings.master>0?m.settings.sfx:0;h.position=i=>m.players[i].truck.transform;return h;}
 void Bindings(){unchecked{int next=count();for(int i=0;i<count();i++){var d=driver(i);next=next*397+(int)d.source;next=next*397+(int)d.forward;next=next*397+(int)d.left;next=next*397+(int)d.back;next=next*397+(int)d.right;next=next*397+(int)d.action;}if(next==signature)return;signature=next;}used.Clear();used.Add(Key.None);used.Add(Key.Escape);used.Add(Key.Enter);used.Add(Key.Space);for(int i=0;i<count();i++){var d=driver(i);if(d.source!=BowlingSource.Keyboard)continue;used.Add(d.forward);used.Add(d.left);used.Add(d.back);used.Add(d.right);used.Add(d.action);}Array.Clear(keys,0,keys.Length);text.Clear();text.Append("HORN");for(int i=0;i<count();i++){var d=driver(i);if(d.source==BowlingSource.AI)continue;if(d.source==BowlingSource.Keyboard)foreach(var key in preferred)if(!used.Contains(key)&&(extraReserved==null||!extraReserved(key))){keys[i]=key;used.Add(key);break;}text.Append("  ·  ").Append(i+1).Append(": ").Append(d.source==BowlingSource.Keyboard?keys[i]==Key.None?"NO FREE KEY":keys[i].ToString().ToUpperInvariant():d.source==BowlingSource.WholeController?"L3":d.source==BowlingSource.LeftStick?"LB":"RB");}Caption=text.ToString();if(help!=null)help.text=Caption;}
 public static bool Held(Driver d,Key key){if(d.source==BowlingSource.Keyboard)return key!=Key.None&&SportsDeviceInput.KeyHeld(key);if(d.pad==null||!d.pad.added||!d.pad.enabled)return false;return d.source==BowlingSource.WholeController?d.pad.leftStickButton.isPressed:d.source==BowlingSource.LeftStick?d.pad.leftShoulder.isPressed:d.source==BowlingSource.RightStick&&d.pad.rightShoulder.isPressed;}
 void Update(){if(owner==null||driver==null)return;Bindings();bool enabled=live()&&focused&&gain()>0;for(int i=0;i<voices.Length;i++){var voice=voices[i];if(i>=count()||!enabled){Stop(i,true);continue;}var d=driver(i);bool held=Held(d,keys[i]);if(!held)armed[i]=true;var anchor=position(i);bool play=held&&armed[i]&&d.released&&d.allowed&&d.source!=BowlingSource.AI&&anchor!=null&&anchor.gameObject.activeInHierarchy;if(!play){Stop(i,false);continue;}voice.transform.position=anchor.position+Vector3.up;voice.volume=gain()*assets.gain;if(!voice.isPlaying){var vehicle=anchor.GetComponentInParent<NWH.VehiclePhysics2.VehicleController>();voice.clip=vehicle!=null&&vehicle.soundManager.hornComponent.Clip!=null?vehicle.soundManager.hornComponent.Clip:assets.defaultHorn;voice.Play();Starts++;}}}
 void Stop(int i,bool reset){if(voices[i]!=null&&voices[i].isPlaying)voices[i].Stop();if(reset)armed[i]=false;}
 public void StopAll(){for(int i=0;i<voices.Length;i++)Stop(i,true);}
 void OnApplicationFocus(bool value){focused=value;if(!value)StopAll();}void OnApplicationPause(bool value){if(value)StopAll();}void OnDisable(){StopAll();}void OnDestroy(){StopAll();foreach(var voice in voices)if(voice!=null)Destroy(voice.gameObject);}
}
